def load_run_log(path):
    rows = []  # (line number, local date, job field, text)
    with open(path, encoding="utf-8", errors="replace") as f:
        for n, line in enumerate(f, 1):
            m = RLDATE.match(line)
            if m:
                parts = line.rstrip("\n").split(" | ")
                rows.append((n, day(m.group(1)), parts[1] if len(parts) > 1 else "", line.rstrip("\n")))
    return rows


def load_changelog(path):
    rows, when = [], (None, None)  # (line number, UTC time or None, local date or None, text)
    with open(path, encoding="utf-8", errors="replace") as f:
        for n, line in enumerate(f, 1):
            line = line.rstrip("\n")
            h, r = HEAD.match(line), ROWDATE.match(line)
            if h:
                d, hh, mm = h.groups()

                local = datetime.strptime(f"{d} {hh}:{mm}", "%Y-%m-%d %H:%M") if hh else None
                when = (local.astimezone(timezone.utc) if local else None, day(d))
            elif line.startswith("#"):
                when = (None, None)
            rows.append((n, None, day(r.group(1)), line) if r else (n, when[0], when[1], line))
    return rows


