def sysctl_int(name):
    try:
        try:
            libc = ctypes.CDLL("/usr/lib/libSystem.B.dylib")
        except OSError:
            libc = ctypes.CDLL(ctypes.util.find_library("c"))
        val = ctypes.c_int(0)
        size = ctypes.c_size_t(ctypes.sizeof(val))
        if libc.sysctlbyname(name.encode(), ctypes.byref(val), ctypes.byref(size), None, 0) == 0:
            return val.value
    except Exception:
        pass
    return None


