    if isinstance(content, str):

        return content
    out = []
    for block in content or []:
        if isinstance(block, dict) and block.get("type") == "text":
            out.append(block.get("text", ""))
    return "\n".join(out)


def scan_transcript(path):
    """Newest compaction summary, Alex's messages after it, last assistant text, screenshot count."""
    last_off, off, images, compactions = 0, 0, 0, 0
    with open(path, "rb") as f:
        for line in f:
            if b'"type":"image"' in line:
                images += 1
            if b'"isCompactSummary":true' in line:
                last_off, compactions = off, compactions + 1
            off += len(line)
    summary, summary_ts, said, last_reply = "", "", [], ""
    with open(path, "rb") as f:
        f.seek(last_off)
        for line in f:
            if (b'"type":"user"' not in line and b'"type":"assistant"' not in line) or (
                    b'"tool_use_id"' in line and b'"isCompactSummary":true' not in line):
                continue
            try:
                e = json.loads(line)
            except Exception:

                continue
            msg = e.get("message") or {}
            if e.get("isCompactSummary"):
                summary, summary_ts, said = text_of(msg.get("content")), e.get("timestamp", ""), []
            elif e.get("type") == "user" and not e.get("isMeta"):
                t = strip_reminders(text_of(msg.get("content")))
                if t.startswith("<command-"):  # a slash command: keep "/name args", drop the wrapper tags
                    t = " ".join(x.strip() for x in re.findall(r"<command-(?:name|args)>(.*?)</command-(?:name|args)>", t, re.S)
                                 if x.strip())
                if t and not t.startswith("<local-command"):
                    said.append((e.get("timestamp", "")[:16], t[:4000]))
            elif e.get("type") == "assistant":
                t = text_of(msg.get("content")).strip()
                if t:
                    last_reply = t[:3000]
    return summary, summary_ts, said, last_reply, images, compactions


