def proc_table():
    # 4 s cap: at critical memory a hung ps costs at most 8 s (stop + top users), well inside the 20 s hook limit
    out = subprocess.run(["ps", "-axo", "pid=,ppid=,rss=,comm="], capture_output=True, text=True, timeout=4).stdout
    procs = {}
    for line in out.splitlines():
        p = line.split(None, 3)
        if len(p) == 4 and p[0].isdigit():
            procs[int(p[0])] = (int(p[1]), int(p[2]), os.path.basename(p[3]))
    return procs


def stop_runaway():
    """Stop the biggest command this chat started (via a shell) if it is over RUNAWAY_MB. Returns a note or ''."""
    try:
        limit_mb = int(os.environ.get("CHAT_GUARD_TEST_RUNAWAY_MB", RUNAWAY_MB))
    except ValueError:
        limit_mb = RUNAWAY_MB
    procs = proc_table()
    mine, p = set(), os.getpid()
    while p in procs and p > 1:
        mine.add(p)
        if procs[p][2] == "claude":

        break
    p = procs[p][0]
root = p if p in procs and procs[p][2] == "claude" else None
if root is None:
    return ""
best = None
for pid, (ppid, rss, name) in procs.items():
    if pid in mine or name in ("zsh", "bash", "sh", "sandbox-exec", "claude") or re.search(r"mcp|server|npx|npm|uvx?$", name, re.I):
        continue
    a, via_shell = ppid, False
    while a in procs and a != root and a > 1:
        if procs[a][2] in ("claude", "codex"):  # belongs to a nested chat this one started, not to this chat
            break
        if procs[a][2] in ("zsh", "bash", "sh", "sandbox-exec"):
            via_shell = True
        a = procs[a][0]
    if a == root and via_shell and rss > limit_mb * 1024 and (best is None or rss > best[1]):
        best = (pid, rss, name)
if not best:
    return ""
pid, rss, name = best
if os.environ.get("CHAT_GUARD_TEST_DRYRUN"):
    return "would stop %s pid %d %.0f MB" % (name, pid, rss / 1024.0)
try:
    os.kill(pid, signal.SIGTERM)

        for _ in range(15):
            time.sleep(0.1)
            os.kill(pid, 0)
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    except Exception as e:
        log("stop failed %d %s" % (pid, e))
        return ""
    log("stopped runaway %s pid %d %.1fGB" % (name, pid, rss / 1048576.0))
    return "Stopped `%s` (pid %d, %.1f GB), a command this chat started, so the Mac doesn't run out of memory." % (
        name, pid, rss / 1048576.0)


def top_users(n=3):
    try:
        procs, groups = proc_table(), {}
        for _, (_, rss, name) in procs.items():
            key = re.sub(r" Helper.*| \(.*\)$", "", name)
            groups[key] = groups.get(key, 0) + rss
        top = sorted(groups.items(), key=lambda kv: -kv[1])[:n]
        return ", ".join("%s %.1f GB" % (k, v / 1048576.0) for k, v in top) or "unknown"
    except Exception:
        return "unknown"


