def shell_text(cmd):
    if isinstance(cmd, list):
        parts = [str(c) for c in cmd]
        if len(parts) >= 3 and os.path.basename(parts[0]) in g.SHELLS and \
                parts[1] in ("-c", "-lc", "-ic", "-lic"):
            return parts[2]
        return " ".join(shlex.quote(p) for p in parts)
    return str(cmd or "")


def normalize(payload):
    """A Claude-shaped payload for composio_guard.decide(), or None when the call is out of scope."""
    name = str(payload.get("tool_name") or "")
    ti = payload.get("tool_input")
    if name in SHELL_TOOLS:
        cmd = ti.get("command", ti.get("cmd")) if isinstance(ti, dict) else ti
        return dict(payload, tool_name="Bash", tool_input={"command": shell_text(cmd)})
    if not name.startswith("mcp__"):
        return None
    if CODEX_LOCAL.match(name):
        # Local JavaScript REPLs can shell out (child_process). Check only code that names composio.

    if JS_REPL.match(name) and isinstance(ti, dict) and "composio" in json.dumps(ti):
        code = "\n".join(v for v in ti.values() if isinstance(v, str))
        lits = re.findall(r"`([^`]*composio[^`]*)`|'([^'\n]*composio[^'\n]*)'|"
                          r"\"([^\"\n]*composio[^\"\n]*)\"", code)
        cmds = [a or b or c for a, b, c in lits]
        if g.SDK_IN_COMMAND.search(code):
            cmds.append(code)
        if cmds:
            return dict(payload, tool_name="Bash", tool_input={"command": "\n".join(cmds)})
    return None
m = re.match(r"^mcp__codex_apps__composio_(composio_[a-z0-9_]+)$", name, re.I)
if m:
    name = "mcp__composio__" + m.group(1).upper()
last = name.split("__")[-1]
if REMOTE_SHELL.search(last) and not last.upper().startswith("COMPOSIO_") and isinstance(ti, dict):
    cmd = ti.get("command", ti.get("cmd", ti.get("script")))
    if isinstance(cmd, (str, list)):
        return dict(payload, tool_name="Bash", tool_input={"command": shell_text(cmd)})

    return dict(payload, tool_name=name)


