def scan_codex_transcript(path, prompt_id=None):
    """Same contract as composio_guard.scan_transcript, for a Codex rollout JSONL file."""
    if not path or not os.path.isfile(path):
        return None, "", False
    meta = _first_line_meta(path) or {}
    if meta.get("originator") not in INTERACTIVE_ORIGINATORS or not isinstance(meta.get("source"), str) \
            or meta.get("source") == "exec":
        return None, "", False                      # headless, exec or subagent: never a yes
    lines, _ = g.read_tail_lines(path, 32_000_000)
    events = []
    for line in lines:
        try:
            e = json.loads(line)
        except Exception:
            continue
        p = e.get("payload") if isinstance(e.get("payload"), dict) else {}

    if e.get("type") != "response_item" or p.get("type") != "message":
        continue
    text = " ".join(c.get("text", "") for c in p.get("content") or []
                    if isinstance(c, dict) and c.get("type") in ("input_text", "output_text"))
    if p.get("role") == "user":
        kinds = (p.get("internal_chat_message_metadata_passthrough") or {}).get(
            "content_item_kinds") or []
        if kinds and all(k == "user.text" for k in kinds) and not text.lstrip().startswith("<"):
            events.append(("human", p.get("id") or e.get("timestamp"), text))
    elif p.get("role") == "assistant" and text:
        events.append(("assistant", None, text))
idx = next((k for k in range(len(events) - 1, -1, -1) if events[k][0] == "human"), None)
if idx is None:
    return None, "", False
ask = []
for k in range(idx - 1, -1, -1):
    if events[k][0] == "human":
        break
    ask.append(events[k][2])
ask.reverse()

    return {"id": events[idx][1], "text": events[idx][2]}, "\n".join(ask), False


