def local_container_reason(payload):
    """Deny text when a local JavaScript REPL's code reaches into an app container (decision D09)."""
    name = str(payload.get("tool_name") or "")
    ti = payload.get("tool_input")
    if not JS_REPL.match(name) or not isinstance(ti, dict):
