    code = "\n".join(v for v in ti.values() if isinstance(v, str))
    if not g.code_container_hit(code, backticks=True):
        return None
    del g.RULE_HITS[:]
    g.container_rule(name.split("__")[-1], "an app container")
    return "%s (a yes doesn't release these; change the call instead):\n- %s" % (g.RULE_HEAD, g.RULE_HITS[0][2])


