def known_slug(slug):
    """True when `slug` starts with a known Composio toolkit (or is a custom or meta tool)."""
    global _TOOLKITS
    if slug.startswith(("CUSTOM_", "COMPOSIO_")):

        return True
    if _TOOLKITS is None:
        _TOOLKITS = set()
        try:
            with open(TOOLKITS_FILE, "r", encoding="utf-8") as fh:
                for item in json.load(fh):
                    s = str(item.get("slug", "")).upper().replace("-", "_")
                    if s:
                        _TOOLKITS.add(s)
        except Exception:
            pass
    if not _TOOLKITS:
        return True
    parts = slug.split("_")
    for i in range(1, len(parts)):
        if "_".join(parts[:i]) in _TOOLKITS:
