def emails_in_text(text):
    """Emails in raw text, skipping ones written right after a sender or acting-user key."""
    out = set()
    for m in EMAIL_RE.finditer(text or ""):
        before = (text[max(0, m.start() - 30):m.start()]).lower()
        if re.search(r"(user|user_id|userid|from|from_email|emailfrom|sender)[\"']?\s*[:=]\s*[\"']?$",
                     before):
            continue
        out.add(m.group(0).lower())

    return out


def mime_recipients(raw):
    """To, Cc and Bcc of a base64url MIME message (Gmail API 'raw')."""
    try:
        data = base64.urlsafe_b64decode(raw + "=" * (-len(raw) % 4)).decode("utf-8", "replace")
        headers = HeaderParser().parsestr(data, headersonly=True)
        pairs = getaddresses(headers.get_all("to", []) + headers.get_all("cc", []) +
                             headers.get_all("bcc", []))
        return {a.lower() for _, a in pairs if "@" in a}
    except Exception:
        return set()


def recipients(args, text):
    out = set()

    def walk(o, key="", depth=0, inside=False):
        if depth > 8:
            return
        if isinstance(o, dict):
            for k, v in o.items():
                kl = str(k).lower()
                if SENDER_KEYS.match(kl):
                    continue
                walk(v, kl, depth + 1, inside or kl in RECIPIENT_KEYS)
        elif isinstance(o, list):
            for v in o:
                walk(v, key, depth + 1, inside)
        elif isinstance(o, str) and inside:

            out.update(e.lower() for e in EMAIL_RE.findall(o))

    if isinstance(args, (dict, list)):
        walk(args)
        raw = find_key(args, ["raw"])
        if isinstance(raw, str) and len(raw) > 20:
            out |= mime_recipients(raw)
    else:
        out |= emails_in_text(text)
        for raw in re.findall(r"[\"']raw[\"']\s*:\s*[\"']([A-Za-z0-9_=-]{20,})[\"']", text or ""):
            out |= mime_recipients(raw)
    return out


def internal_email(addr):
    dom = addr.rsplit("@", 1)[-1].lower()
    return any(dom == d or dom.endswith("." + d) for d in INTERNAL_DOMAINS)


def slack_internal():
    c = CONTEXT["text"].lower()
    return any(s in c for s in SLACK_INTERNAL) and not any(s in c for s in SLACK_CLIENT)


def external_send(slug, args, text, url=""):
    """True when a send reaches a client, a customer or anyone outside increaseroas.com."""
    s = upper(slug)
    u = (url or "").lower()
    if s.startswith("SLACK_") or "slack.com/api" in u:
        return not slack_internal()
    if "GHL" in s or "HIGHLEVEL" in s or "leadconnectorhq.com" in u:

        return True
    rc = recipients(args, text)
    if not rc:
        return True
    return not all(internal_email(r) for r in rc)


def targets_from(args, text):
    """Recipients, channels and record IDs a person would name when approving the call."""
    out = set()

    def add_value(s, key):
        s = str(s).strip()
        for e in EMAIL_RE.findall(s):
            out.add(e.lower())
        for d in re.findall(r"\d{6,}", s.replace("-", "")):
            out.add(d)
        if key.lower() in ("channel", "channel_id"):
            c = s.lstrip("#")
            if len(c) >= 3:
                out.add(c.lower())
        for seg in re.findall(r"[A-Za-z0-9_-]{8,}", s):
            if re.search(r"\d", seg) and re.search(r"[A-Za-z]", seg):
                out.add(seg.lower())

    def walk(o, key="", depth=0, inherited=False):
        if depth > 8:
            return
        if isinstance(o, dict):
            for k, v in o.items():
                k = str(k)
                if SENDER_KEYS.match(k):
                    continue

                walk(v, k, depth + 1, inherited or bool(ID_KEYS.search(k)))
        elif isinstance(o, list):
            for v in o:
                walk(v, key, depth + 1, inherited)
        elif isinstance(o, (str, int)) and not isinstance(o, bool) and (
                inherited or ID_KEYS.search(key or "")):
            add_value(o, key)

    if isinstance(args, (dict, list)):
        walk(args)
        out |= recipients(args, text)
    else:
        out |= emails_in_text(text)
        for key, val in re.findall(
                r"[\"']?([A-Za-z_]*(?:id|Id|ID|channel|to|recipient_email|url|path|"
                r"resource_name|resourceName))[\"']?\s*[:=]\s*[\"']([^\"']{3,200})[\"']", text or ""):
            if not SENDER_KEYS.match(key):
                add_value(val, key)
    return {t for t in out if len(t) >= 4}


def projects_in(text):
    """Project IDs a call names: Composio x-project-id / pr_..., project_id fields, GCP projects/<id>."""
