def segment_runs_nothing(words):
    """True when a simple command can't run a file it names: viewers, file operations, git, and the

    non-executing forms of sed, awk, find, shells (-n), python (-m py_compile) and node (--check)."""
    w = command_words(words)
    if not w:
        return True
    b = os.path.basename(w[0])
    args = w[1:]
    if b in NON_EXEC:
        return True
    if b in ("sed", "gsed"):
        return not sed_runs(args)
    if b in ("awk", "gawk", "nawk", "mawk"):
        return not awk_runs(args)
    if b == "find":
        return not any(a in ("-exec", "-execdir", "-ok", "-okdir") for a in args)
    if b == "git":
        return git_runs_nothing(args)
    if b in SHELLS or b == "fish":
        return bool(args) and args[0] == "-n"
    if PY_RE.match(b):
        return python_compiles_only(args)
    if b == "node":
        return bool(args) and args[0] in ("--check", "-c")
    return False


