def is_record_segment(seg):

    """True for `python3 <the Director's accept.py, graph_edit.py, graph_lint.py or ledger_check.py>`."""
    w = command_words(seg["words"])
    if len(w) < 2 or not PY_RE.match(os.path.basename(w[0])):
