FILEISH_TOOL = re.compile(r"(read|list|search|file|director|path|write|move|copy|edit|start_process|"
                          r"interact|execute|run|bash|shell|terminal|command|glob|grep|find|tree|stat|"
                          r"info)", re.I)


def path_like(tok):
    return bool(re.match(r"^(~|\$\{?HOME\}?|/|\.\.?/)", tok or ""))


def code_container_hit(code, backticks=True):
    """True when code holds a string literal that starts with a container path."""
    for m in CODE_CONTAINER.finditer(code or ""):
        if m.group(1) == "`" and not backticks:

            continue
        return True
    return False


def js_like(name):
    return bool(re.match(r"^(node|deno|bun|tsx|ts-node|ruby|perl|php)$", name or ""))


def container_hit_token(tok, base_dir):
    """True when one shell word names a path inside an app container. Text only: nothing is read."""
    t = tok[1:] if tok.startswith("@") else tok
    m = re.match(r"^--?[A-Za-z][\w-]*=(.+)$", t)
    if m:
        t = m.group(1)
    if not (path_like(t) or "containers" in t.lower()):
        return False
    p, _ = resolve_literal(t, base_dir)
    if p is None:
        return bool(CONTAINER_TEXT.search(t))
    return under_container(p) or glob_reaches_container(p)


def depth_limit(args, flags):
    for k, a in enumerate(args):
        if a in flags and k + 1 < len(args) and args[k + 1].isdigit():
            return int(args[k + 1])
        for f in flags:
            if f.startswith("--") and a.startswith(f + "=") and a[len(f) + 1:].isdigit():
                return int(a[len(f) + 1:])
    return None


