def container_hits_bash(cmd, cwd, depth=0):
    """Short labels for the parts of a shell command that reach into an app container."""
    hits = []
    stripped, bodies = split_heredocs(cmd)
    try:
        segs = walk_segments(stripped, cwd)
    except Exception:
        return ["an unparsed command"] if CONTAINER_TEXT.search(cmd) else []
    for s in segs:
        w = command_words(s["words"])
        if not w:
            continue
        b = os.path.basename(w[0])
        if walks_into_containers(w, s["dir"]):
            hits.append("a %s over ~ or ~/Library" % b)
        for k, a in enumerate(w):
            prev = w[k - 1] if k else ""
            if k and (b in SHELLS or b == "fish") and code_flag(prev):
                if depth < 2:
                    hits += container_hits_bash(a, s["dir"], depth + 1)
            elif k and b == "eval":
                if depth < 2:
                    hits += container_hits_bash(" ".join(w[1:]), s["dir"], depth + 1)
                break

            elif k and INTERPRETERS.match(b) and prev in ("-c", "-e", "--eval", "-p", "--print", "-E"):
                if code_container_hit(a, js_like(b)):
                    hits.append("%s code" % b)
            elif container_hit_token(a, s["dir"]):
                hits.append(a if len(a) <= 100 else a[:97] + "...")
    for line, body, _quoted in bodies:
        m = re.search(r"\b(python\d*(\.\d+)?|node|deno|bun|tsx|ruby|perl|php|osascript|bash|sh|zsh|dash)\b", line)
        if not m:
            continue                                     # data for cat, tee and the like
        if m.group(1) in SHELLS and depth < 2:
            hits += container_hits_bash(body, cwd, depth + 1)
        elif code_container_hit(body, js_like(m.group(1))):
            hits.append("here-document code")
    return list(dict.fromkeys(hits))


def container_hits_mcp(tool_name, tool_input, cwd):
    """The same check for MCP tools that touch files or run commands (Desktop Commander and the like)."""
    if not FILEISH_TOOL.search(tool_name.split("__")[-1]):
        return []
    hits = []

    def walk(o, key, depth):
        if depth > 6:
            return
        if isinstance(o, dict):
            for k, v in o.items():
                walk(v, str(k).lower(), depth + 1)
        elif isinstance(o, list):
            for v in o:
                walk(v, key, depth + 1)
        elif isinstance(o, str):
            v = o.strip()
            if key in ("command", "cmd", "shell", "input", "script"):
                hits.extend(container_hits_bash(o, cwd))
            elif key in ("code", "javascript", "js", "python", "code_to_execute"):
                if code_container_hit(o, key not in ("python", "code_to_execute")):
                    hits.append("code")
            elif (path_like(v) or v.lower().startswith("library/")) and container_hit_token(v, cwd):
                hits.append(v if len(v) <= 100 else v[:97] + "...")

    walk(tool_input, "", 0)
    return list(dict.fromkeys(hits))


