def iter_slug_calls(obj, depth=0):
    """(slug, arguments, account) from Composio meta-tool inputs such as COMPOSIO_MULTI_EXECUTE_TOOL."""
    if depth > 6:
        return
    if isinstance(obj, dict):
        slug = obj.get("tool_slug") or obj.get("toolSlug")
        if isinstance(slug, str):
            args = obj.get("arguments", obj.get("args", obj.get("input", obj.get("params"))))
            account = obj.get("account") or obj.get("connected_account_id") or obj.get("connectedAccountId")
            yield slug, args, account
            return
        for v in obj.values():
            for r in iter_slug_calls(v, depth + 1):
                yield r
    elif isinstance(obj, list):
        for v in obj:
            for r in iter_slug_calls(v, depth + 1):

                yield r


def analyze_mcp(tool_name, tool_input, cwd):
    if LOCAL_MCP.match(tool_name):
        return []
    tool_up = tool_name.split("__")[-1].upper().replace("-", "_")
    findings = []
    calls = list(iter_slug_calls(tool_input))
    for slug, args, account in calls:
        if not account and toolkit_of(slug) in MULTI_LOGIN:
            login_rule(upper(slug), toolkit_of(slug))
        argsj = try_json(args) if isinstance(args, str) else args
        f = finding_for(slug, argsj, as_text(args))
        if f:
            findings.append(f)
    if calls:
        return findings
    if tool_up == "COMPOSIO_REMOTE_WORKBENCH" or (
            isinstance(tool_input, dict) and "code_to_execute" in tool_input):
        return analyze_code(as_text(find_key(tool_input, ["code_to_execute", "code"])))
    if tool_up == "COMPOSIO_REMOTE_BASH_TOOL":
        return analyze_bash(as_text(find_key(tool_input, ["command"])), cwd)
    if tool_up.startswith("COMPOSIO_"):
        return []

    # App MCP tools (hub routes, claude.ai connectors, plugin servers): the tool name is the action.
    f = finding_for(tool_up, tool_input, as_text(tool_input))
    return [f] if f else []


