def with_settings(config, settings):
    """Set each CODEX_SETTINGS key at the top level of config.toml: replace its line in place, or add it at the top.
    Lines inside the generated developer_instructions string and anything after the first [table] are never touched."""
    out, seen, in_block, top = [], set(), False, True
    for line in config.splitlines(keepends=True):
        s = line.strip()
        if in_block:
            in_block = s != "'''"
        elif s.startswith("developer_instructions = '''"):
            in_block = s.count("'''") == 1
        elif top and s.startswith("["):
            top = False
        elif top:
            m = re.match(r"([A-Za-z0-9_-]+)\s*=", s)
            if m and m.group(1) in settings:
                line = f"{m.group(1)} = {json.dumps(settings[m.group(1)])}\n"
                seen.add(m.group(1))

        out.append(line)
    return "".join(f"{k} = {json.dumps(v)}\n" for k, v in settings.items() if k not in seen) + "".join(out)


def app_sections(text):
    """The APP_SECTIONS of codex-style.md, in APP_SECTIONS order, as top-level '# ' sections for AGENTS.md.
    Only the heading level changes ('## Voice' -> '# Voice'); every line under a heading is copied as is."""
    parts = {p.splitlines()[0][3:].strip(): p for p in re.split(r"(?m)^(?=## )", text) if p.startswith("## ")}
    for s in APP_SECTIONS:
        if s not in parts:
            sys.exit(f"codex-style.md has no '## {s}' section")
    return "\n".join(parts[s][1:].rstrip() + "\n" for s in APP_SECTIONS)


