def safe_path(raw):
    """Resolve a cited path without opening it. Returns (abs_path, kind) or (None, reason)."""
    p = os.path.expanduser(raw) if raw.startswith("~") else raw if raw.startswith("/") else os.path.join(REPO, raw)
    if protected(p):
        return None, "refused: another app's private folder (STOP-RULE, never touched)"
    base = os.path.basename(p.rstrip("/"))
    if base.endswith(".env") or base.startswith(".env"):
        return None, "refused: .env path (STOP-RULE)"
    try:
        st = os.lstat(p)
    except (FileNotFoundError, NotADirectoryError):
        return None, "missing"
    if stat.S_ISLNK(st.st_mode):
        if protected(os.path.join(os.path.dirname(p), os.readlink(p))):
            return None, "refused: a link into another app's private folder (STOP-RULE, never touched)"
        try:
            st = os.stat(p)
        except FileNotFoundError:
            return None, "broken link"
    if stat.S_ISREG(st.st_mode):
        return p, "file"
    if stat.S_ISDIR(st.st_mode):

        return p, "dir"
    return None, "not a regular file (refused, never opened)"


