def check_locator(path, kind, loc, problems):
    if kind != "file" or not loc:
        return
    text = None
    for q in re.findall(r'"([^"]+)"', loc):
        text = text or read_text(path)
        if q.lower() not in text.lower():
            problems.append(f"quoted text not found in {rel(path)}: {q!r}")
    bare = re.sub(r'"[^"]*"', " ", loc)
    bare = re.sub(r"\([^)]*\)", " ", bare)
    rows_cited = re.findall(r"\brow ([A-Z]+\d+(?:-[A-Z]+\d+)?)\b", bare)
    bare_lines = re.sub(r"\brow [A-Z]+\d+(?:-[A-Z]+\d+)?\b", " ", bare)
    for a, b in re.findall(r"(?<![\w-])L(\d+)(?:[–-]L?(\d+))?(?![\w-])", bare_lines):
        text = text or read_text(path)

        n = text.count("\n") + (0 if text.endswith("\n") else 1)
        if int(b or a) > n:
            problems.append(f"{rel(path)} has {n} lines, cited L{b or a}")
    for sec in re.findall(r"§(\d+)", bare):
        text = text or read_text(path)
        if not re.search(rf"(?m)^#+\s*(?:§)?{sec}[.\s:)]", text):
            problems.append(f"{rel(path)} has no heading numbered {sec}")
    for rid in rows_cited:
        if path.endswith(".csv"):
            ids = {r[0] for r in csv.reader(open(path, encoding="utf-8")) if r}
            if rid not in ids:
                problems.append(f"{rel(path)} has no row {rid}")
    for lid in re.findall(r"\b(L-\d{3})\b", loc):
        text = text or read_text(path)
        if f"### {lid}" not in text:
            problems.append(f"{rel(path)} has no lesson {lid}")
    if "docstring" in bare and path.endswith(".py"):
        import ast
        if not ast.get_docstring(ast.parse(read_text(path))):
            problems.append(f"{rel(path)} has no docstring")


