def client_names():
    names = set()
    p = f"{REPO}/knowledge/clients.md"
    for line in read_text(p).splitlines():
        if not line.startswith("|") or line.startswith("|---") or line.startswith("| Name") or line.startswith("| Company"):
            continue
        first = line.strip("|").split("|")[0]
        for n in re.split(r"[(),]", first):
            n = re.sub(r"\*", "", n).strip()

            if len(n) >= 5 and n.lower() not in OWN:
                names.add(n)
    return names


def scan_text(label, text, names, problems, warnings):
    for rule, rx in SECRET:
        if re.search(rx, text):
            problems.append(f"{label}: looks like a secret ({rule}); text not shown")
    for n in names:
        if re.search(r"(?<![A-Za-z])" + re.escape(n) + r"(?![A-Za-z])", text, re.I):
            problems.append(f"{label}: client name from knowledge/clients.md")
    for e in re.findall(r"[\w.+-]+@[\w-]+\.[\w.]+", text):
        if e.lower() not in {"alex@increaseroas.com"} and not e.lower().startswith("noreply@"):
            problems.append(f"{label}: email other than alex@increaseroas.com")
    if re.search(r"\bact_\d{6,}", text):
        problems.append(f"{label}: Meta ad account id")
    for tok in re.findall(r"\b[A-Za-z0-9]{20}\b", text):
        if re.search(r"[a-z]", tok) and re.search(r"[A-Z]", tok) and re.search(r"\d", tok):
            problems.append(f"{label}: looks like a GHL location id")

    if re.search(r"\b[a-z0-9]{26}\b", text) and len(re.findall(r"\d", " ".join(re.findall(r"\b[a-z0-9]{26}\b", text)))) >= 3:
        warnings.append(f"{label}: looks like a 1Password item id")
    if re.search(r"\(\d{3}\)\s?\d{3}-\d{4}|\+1\d{10}\b", text):
        problems.append(f"{label}: phone number")


