def scan_bytes(data, counts, triage, where, depth=0):
    if data[:4] == b"PK\x03\x04" and depth < 4:
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as z:
                counts["_zip_members"] = counts.get("_zip_members", 0) + len(z.namelist())
                for info in z.infolist():
                    if info.is_dir():
                        continue
                    scan_bytes(z.read(info), counts, triage, where + "!" + info.filename, depth + 1)
            return
        except Exception as e:  # corrupt zip: fall through to raw scan
            counts["_zip_error"] = counts.get("_zip_error", 0) + 1

    if b"\x00" in data[:8192]:
        counts["_binary"] = counts.get("_binary", 0) + 1
        text = data.decode("latin-1")
    else:
        text = data.decode("utf-8", errors="replace")
    scan_text(text, counts, triage, where)


