def scrub(self, text, personal=True):
    """personal=False keeps public-mail addresses (LICENSE-style credit files); everything else is the same."""
    if not text:
        return text
    self._personal = personal
    try:
        text = EMAIL.sub(self._email, text)
    finally:
        self._personal = True
    for rx in (GFILE_PATH, GFILE_QUERY):
        text = rx.sub(lambda m: m.group(1) + GFILE_LABEL, text)
    if self.gfile_rx:
        text = self.gfile_rx.sub(GFILE_LABEL, text)

    if self.owner_rx:
        text = self.owner_rx.sub(lambda m: self.owner_label[m.group(0).lower()], text)
    text = PARTNER_RX.sub(PARTNER_LABEL, text)
    text = HOST.sub(lambda m: self.scrub_host(m.group(1)), text)
    if self.phone_rx:
        text = self.phone_rx.sub(lambda m: self.phone_label[re.sub(r"\D", "", m.group(0))[-10:]], text)
    if self.id_rx:
        text = self.id_rx.sub(lambda m: self.id_label[m.group(0)], text)
    if self.name_rx:
        text = self.name_rx.sub(lambda m: render(self.client_of(m)[0].code, m.group(0), self.client_of(m)[1]), text)
    return text

