# ------------------------------------------------------------------ harvest by context
def harvest(self, units):
    """IDs, emails and phones written next to a client's name join that client. Each mention votes: 3 when the
    name follows right after the ID ('543642271 Paradise Spas'), 1 when it is nearby. Our own names vote too; the

client keeps the ID only with more votes than ours (a tie stays ours)."""
votes, order = {}, []
known = set(self.id_label) | self.own_ids
for _, text in units:
    if not text or not self.name_rx:
        continue
    anchors = [(m.start(), m.end(), self.client_of(m)[0]) for m in self.name_rx.finditer(text)]
    if not anchors:
        continue
    anchors += [(m.start(), m.end(), None) for m in self.own_rx.finditer(text)]
    anchors.sort(key=lambda a: a[0])
    for kind, value, s, e in self._candidates(text):
        if value in known:
            continue
        owner, weight = _nearest(anchors, s, e, text)
        if owner is False:
            continue
        key = (kind, value)
        if key not in votes:
            votes[key] = {}
            order.append(key)
        who = "own" if owner is None else owner.code
        votes[key][who] = votes[key].get(who, 0) + weight

    by_code = {c.code: c for c in self.clients}
    taken = {k: 0 for k in ("ghl", "meta_account", "meta_id", "num", "email", "phone")}
    for key in order:
        own = votes[key].pop("own", 0)
        if not votes[key]:
            continue
        code, score = max(votes[key].items(), key=lambda kv: kv[1])
        if score <= own:
            continue
        kind, value = key
        c = by_code[code]
        bucket = c.emails if kind == "email" else c.phones if kind == "phone" else c.ids[kind]
        if value not in bucket:
            bucket.append(value)
            taken[kind] += 1
    self._id_index()
    return taken

def _candidates(self, text):
    for m in GHL_ID.finditer(text):
        if _mixed(m.group(0)):
            yield "ghl", m.group(0), m.start(), m.end()
    for m in NUM_ID.finditer(text):
        v = m.group(0)
        kind = "meta_account" if text[max(0, m.start() - 4):m.start()] == "act_" else "meta_id" if len(v) >= 15 else "num"

            yield kind, v, m.start(), m.end()
        for m in EMAIL.finditer(text):
            if not m.group(1).lower().endswith(OWN_EMAIL_DOMAINS):
                yield "email", m.group(0).lower(), m.start(), m.end()
        for m in PHONE.finditer(text):
            yield "phone", re.sub(r"\D", "", m.group(0))[-10:], m.start(), m.end()


def _nearest(anchors, s, e, text=""):
    """Who the identifier at s..e belongs to, with the weight of that vote: a name starting right after it
    ('543642271 Paradise Spas', weight 3), else the closest name ending before it (within WINDOW_BEFORE), else the
    first one starting after it (within WINDOW_AFTER), weight 1. The owner is a Client, None for our own name, or
    False when no name is near."""
    i = bisect.bisect_right([a[1] for a in anchors], s)  # anchors sorted by start; ends rise with starts here
    for a in anchors[i:]:
        if a[0] >= e:
            if a[0] - e <= 2 and not re.search(r"[A-Za-z0-9,;]", text[e:a[0]]):
                return a[2], 3
            break

    best = next((a for a in anchors[:i][::-1] if a[1] <= s), None)
    if best and s - best[1] <= WINDOW_BEFORE:
        return best[2], 1
    for a in anchors[i:]:
        if a[0] >= e:
            return (a[2], 1) if a[0] - e <= WINDOW_AFTER else (False, 0)
    return False, 0


