def read_affiliates(composio=None):
    """Alex's live affiliate links, read at build time from his Sheet through Composio custom_google_robot sheets_read
    as alex@. Any problem stops the build (SystemExit): there is no stored copy, so old links can never come back."""
    def fail(why):
        raise SystemExit(f"affiliate Sheet not read ({why}); build stopped before anything was built, so the old edition "
                         "is kept and no old links are reused")
    cmd = [composio or COMPOSIO, "execute", SHEETS_READ, "--account", GOOGLE_ROBOT, "-d",
           json.dumps({"spreadsheet_id": AFFILIATE_SHEET, "range": AFFILIATE_RANGE, "user": SHEET_USER})]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=SHEET_TIMEOUT)
    except subprocess.TimeoutExpired:
        fail(f"Composio ran over {SHEET_TIMEOUT} s and was stopped")
    except OSError as e:

        fail(f"the Composio CLI did not start: {e.strerror}")
    if r.returncode != 0:
        last = (r.stderr.strip() or r.stdout.strip()).splitlines()[-1:] or [""]
        fail(f"Composio exit {r.returncode}: {_redact(last[0])[:200]}")
    try:
        out = json.loads(r.stdout)
    except ValueError:
        fail("Composio's answer is not JSON")
    if not isinstance(out, dict) or out.get("successful") is not True:
        fail("Composio says: " + _redact(str(out.get("error") if isinstance(out, dict) else out))[:200])
    values = _values(out.get("data"))
    if not values or not isinstance(values[0], list):
        fail(f"no rows came back for {AFFILIATE_RANGE}")
    return parse_affiliates(values)


