def product_hosts(tool, urls):
    """The product's own web hosts, taken from the row's program and source URLs: a host whose site name matches the
    tool (gohighlevel.com for "HighLevel (GoHighLevel)"); apex and www count together, another subdomain only as itself
    (workspace.google.com), and never a help, docs, API, app, login or partner host."""
    name = squash(tool)

    parts = {squash(w) for w in re.split(r"[^A-Za-z0-9]+", tool)} - {""}
    hosts = set()
    for u in urls:
        try:
            h = (urllib.parse.urlsplit(u).hostname or "").rstrip(".")
        except ValueError:
            continue
        labels = h.split(".")
        if len(labels) < 2:
            continue
        n = 3 if len(labels) >= 3 and len(labels[-1]) == 2 and labels[-2] in ("co", "com", "org", "net", "ac", "gov") else 2
        site, sub = labels[-n], labels[:-n]
        if not (site == name or (len(site) >= 4 and site in name)
                or any(len(w) >= 6 and w not in GENERIC_WORDS and w in site for w in parts)):
            continue  # someone else's site (an affiliate network, a directory, a social network)
        if sub[:1] == ["www"]:
            sub = sub[1:]
        if any(piece in SITE_SKIP for label in sub for piece in label.split("-")):
            continue
        apex = ".".join(labels[-n:])
        hosts |= {h} if sub else {apex, "www." + apex}
    return hosts


def link_kind(url, hosts):

    """"home", "pricing" or "sign-up" when url is one of these hosts' own home, pricing or sign-up page; None for
    anything else (API, docs, help, app and login hosts aren't in hosts, and no other path counts)."""
    try:
        p = urllib.parse.urlsplit(url)
        host, port = (p.hostname or "").rstrip("."), p.port
    except ValueError:
        return None
    if p.scheme.lower() not in ("http", "https") or port or p.username or host not in hosts:
        return None
    if p.path in ("", "/"):
        return "home"
    if PRICING_PATH.fullmatch(p.path):
        return "pricing"
    if SIGNUP_PATH.fullmatch(p.path):
        return "sign-up"
    return None


