def _cell_swap(text, live, label):
    """A workbook text: line by line like a doc; JSON-looking cells, shell-command lines and inline code stay."""
    if text.lstrip().startswith(("{", "[")) or re.search(r'"[\w$.-]+"\s*:', text):
        return text, 0
    out, n = [], 0
    for line in text.splitlines(keepends=True):
        body = line.rstrip("\r\n")
        if COMMAND.match(body):
            out.append(line)
            continue
        new, k = _swap_outside_code(body, live, label)
        out.append(new + line[len(body):])
        n += k
    return "".join(out), n


